item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure; repeated testing is unspecified. MESA 16: variation across runs is not established."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run provides no evidence of stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14: No; repeated testing explicitly did not occur. MESA 16: stability across runs remains unestablished."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes; repeated testing occurred. MESA 16: the reported range supports stability under the stated criterion and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers measured variation across repeated runs under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes; testing occurred despite unfavourable results. MESA 16: reported variation contradicts stability under the stated criterion."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no evidence about variation across runs."
        }
      ],
      "instrument_review": "MESA 14: Not sure; repetition remains unspecified. Installation guidance relates to MESA 22 reproducibility documentation, but does not establish score stability."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results provide no evidence establishing general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 20 and 25: the observed comparison supports the narrow intended use. Extending it to general intelligence lacks evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use does not supply evidence of broader ability."
        }
      ],
      "instrument_review": "MESA 9 and 20: cross-domain coverage and generalization are not established. Under MESA 25, using these results to select for general intelligence exceeds the supplied evidence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone do not establish improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings do not establish an improvement in unmeasured safety outcomes."
        }
      ],
      "instrument_review": "MESA 20: the later trial supplies evidence beyond test scores for workshop decision correctness. MESA 16: the difference interval supports that comparison. MESA 25: claims should remain limited to correctness in the studied conditions."
    }
  ],
  "closing_note": "No instructions were unclear. Probe labels classify evidential support, separately from MESA ratings; missing evidence was not treated as contradiction."
}
